FROM ((`m_pelanggan` `p` left join `m_wilayah` `w` on((`p`.`kode_wilayah_kelurahan_ktp` = `w`.`kode_wilayah_kelurahan`))) left join `m_status_hide` `h` on((`p`.`hide` = `h`.`hide`)));

-- 4. view_divisi_jabatan
CREATE VIEW `view_divisi_jabatan` AS 
SELECT `d`.`kode_divisi` AS `kode_divisi`, `d`.`nama_divisi` AS `nama_divisi`, `d`.`desc_divisi` AS `desc_divisi`, `j`.`kode_jabatan` AS `kode_jabatan`, `j`.`nama_jabatan` AS `nama_jabatan`, `j`.`desc_jabatan` AS `desc_jabatan` 
FROM (`tb_m_jabatan` `j` left join `tb_m_divisi` `d` on((`j`.`kode_divisi` = `d`.`kode_divisi`)));

-- 5. view_karyawan
CREATE VIEW `view_karyawan` AS 
SELECT `k`.`kode_karyawan` AS `kode_karyawan`, `k`.`kantor` AS `kantor`, `k`.`nik` AS `nik`, `k`.`nip` AS `nip`, `k`.`nama_karyawan` AS `nama_karyawan`, `k`.`kode_jabatan` AS `kode_jabatan`, `jb`.`nama_jabatan` AS `nama_jabatan`, `jb`.`kode_divisi` AS `kode_divisi`, `jb`.`nama_divisi` AS `nama_divisi`, `jb`.`desc_jabatan` AS `desc_jabatan`, `k`.`jenis_kelamin` AS `jenis_kelamin`, `k`.`hp_karyawan` AS `hp_karyawan`, `k`.`kode_agama` AS `kode_agama`, `ag`.`nama_agama` AS `nama_agama`, `k`.`email_karyawan` AS `email_karyawan`, `k`.`email_msn` AS `email_msn`, `k`.`tempat_lahir` AS `tempat_lahir`, `k`.`tanggal_lahir` AS `tanggal_lahir`, `k`.`tempat_pendidikan_terakhir` AS `tempat_pendidikan_terakhir`, `k`.`kode_pendidikan` AS `kode_pendidikan`, `pd`.`nama_pendidikan` AS `nama_pendidikan`, `k`.`jmlh_tanggungan` AS `jmlh_tanggungan`, `k`.`desc_tanggungan` AS `desc_tanggungan`, `k`.`kode_golongan_darah` AS `kode_golongan_darah`, `gl`.`nama_golongan_darah` AS `nama_golongan_darah`, `k`.`kode_wilayah_kelurahan` AS `kode_wilayah_kelurahan`, `kl`.`nama_kelurahan` AS `nama_kelurahan`, `kl`.`kode_wilayah_kecamatan` AS `kode_wilayah_kecamatan`, `kl`.`nama_kecamatan` AS `nama_kecamatan`, `kl`.`kode_wilayah_kota` AS `kode_wilayah_kota`, `k`.`kota_kerja` AS `kota_kerja`, `kl`.`nama_kota` AS `nama_kota`, `kl`.`kode_provinsi` AS `kode_provinsi`, `kl`.`nama_provinsi` AS `nama_provinsi`, `k`.`ktp` AS `ktp`, `k`.`cv` AS `cv`, `k`.`foto` AS `foto`, `k`.`ijazah_pendidikan_terakhir` AS `ijazah_pendidikan_terakhir`, `k`.`alamat_asal` AS `alamat_asal`, `k`.`domisili` AS `domisili`, `k`.`kode_status_kawin` AS `kode_status_kawin`, `sk`.`nama_status_kawin` AS `nama_status_kawin`, `k`.`npwp` AS `npwp`, `k`.`bpjs` AS `bpjs`, `k`.`bank_rek` AS `bank_rek`, `k`.`no_rek` AS `no_rek`, `k`.`tanggal_masuk` AS `tanggal_masuk`, `k`.`tanggal_keluar` AS `tanggal_keluar`, `k`.`status_rumah` AS `status_rumah`, `k`.`kendaraan` AS `kendaraan`, `k`.`status_kontrak` AS `status_kontrak`, `k`.`berat` AS `berat`, `k`.`tinggi` AS `tinggi`, `k`.`sim` AS `sim`, `k`.`status_aktif` AS `status_aktif`, `k`.`date_create` AS `date_create`, `k`.`user_create` AS `user_create`, `k`.`user_update` AS `user_update`, `k`.`date_update` AS `date_update`, `k`.`uid` AS `uid` 
FROM ((((((`tb_m_karyawan` `k` left join `tb_m_agama` `ag` on((`k`.`kode_agama` = `ag`.`id_agama`))) left join `tb_m_golongan_darah` `gl` on((`k`.`kode_golongan_darah` = `gl`.`id_golongan_darah`))) left join `view_divisi_jabatan` `jb` on((`k`.`kode_jabatan` = `jb`.`kode_jabatan`))) left join `tb_m_pendidikan` `pd` on((`k`.`kode_pendidikan` = `pd`.`id_pendidikan`))) left join `tb_m_status_kawin` `sk` on((`k`.`kode_status_kawin` = `sk`.`id_status_kawin`))) left join `m_wilayah` `kl` on(((convert(`k`.`kode_wilayah_kelurahan` using utf8mb4) collate utf8mb4_unicode_ci) = `kl`.`kode_wilayah_kelurahan`)));

-- 6. view_pengguna
CREATE VIEW `view_pengguna` AS 
SELECT `p`.`kode_pengguna` AS `kode_pengguna`, `p`.`kode_karyawan` AS `kode_karyawan`, `k`.`nama_karyawan` AS `nama_karyawan`, `p`.`kode_level` AS `kode_level`, `l`.`level` AS `level`, `l`.`nama_level` AS `nama_level`, `p`.`username` AS `username`, `p`.`password` AS `password`, `p`.`status_aktif` AS `status_aktif`, `p`.`as_sales` AS `as_sales`, `k`.`nip` AS `nip`, `k`.`nama_jabatan` AS `nama_jabatan`, `k`.`kode_divisi` AS `kode_divisi`, `k`.`nama_divisi` AS `nama_divisi`, `k`.`foto` AS `foto`, `k`.`kota_kerja` AS `kota_kerja`, `p`.`last_ip` AS `last_ip`, `p`.`las_login` AS `las_login` 
FROM ((`tb_pengguna` `p` left join `tb_m_level_pengguna` `l` on((`l`.`kode_level` = `p`.`kode_level`))) left join `view_karyawan` `k` on((`k`.`kode_karyawan` = `p`.`kode_karyawan`)));

