FROM (((((((`trx_batchjob_register` `br` left join `m_status_registrasi` `sr` on((`br`.`status_reg` = `sr`.`status_reg`))) left join `trx_instalasi` `i` on((`br`.`nomor_internet` = `i`.`nomor_internet`))) left join `view_bandwith` `b` on((`br`.`kode_bandwith` = `b`.`kode_bandwith`))) left join `m_wilayah` `w` on((`br`.`kode_wilayah_kelurahan_pasang` = `w`.`kode_wilayah_kelurahan`))) left join `view_pelanggan` `p` on((`br`.`id_perusahaan` = `p`.`id_perusahaan`))) left join `m_status_hide` `h` on((`br`.`hide` = `h`.`hide`))) left join `m_pop` `po` on((`po`.`kode_pop` = `br`.`kode_pop`)));

-- 8. view_aktif_kota
CREATE VIEW `view_aktif_kota` AS 
SELECT `view_batchjob`.`nama_kota_pasang` AS `nama_kota`, `view_batchjob`.`kode_wilayah_kota_pasang` AS `kode_kota` 
FROM `view_batchjob` 
GROUP BY `view_batchjob`.`nama_kota_pasang`, `view_batchjob`.`kode_wilayah_kota_pasang`;

-- 9. view_suspend
CREATE VIEW `view_suspend` AS 
SELECT `s`.`kode_suspend` AS `kode_suspend`, `s`.`nomor_internet` AS `nomor_internet`, `b`.`status_reg` AS `status_reg`, `b`.`desc_registrasi` AS `desc_registrasi`, `b`.`nik_penduduk` AS `nik_penduduk`, `b`.`nama_pelanggan` AS `nama_pelanggan`, `b`.`nama_penduduk` AS `nama_penduduk`, `b`.`nomor_hp` AS `nomor_hp`, `b`.`email` AS `email`, `b`.`jenis_kelamin` AS `jenis_kelamin`, `b`.`kode_wilayah_kota_pasang` AS `kode_wilayah_kota_pasang`, `b`.`pic` AS `pic`, `b`.`nama_kategori_bandwith` AS `nama_kategori_bandwith`, `b`.`nominal_bandwith` AS `nominal_bandwith`, `b`.`jenis_bangunan` AS `jenis_bangunan`, `b`.`alamat_p` AS `alamat_p`, `b`.`harga_bandwith` AS `harga_bandwith`, `b`.`user_create` AS `sales_create`, `s`.`suspend_start` AS `suspend_start`, `s`.`suspend_end` AS `suspend_end`, `s`.`status_suspend` AS `status_suspend`, `ss`.`desc_status_suspend` AS `desc_status_suspend`, `s`.`desc_suspend` AS `desc_suspend`, `s`.`date_create` AS `date_create`, `s`.`user_create` AS `user_create`, `s`.`date_update` AS `date_update`, `s`.`user_update` AS `user_update`, `s`.`hide` AS `hide` 
